extensionAttribute.scriptContentsMac:
#!/bin/zsh
# Updated by SecurityShrimp 2026 # File Sharing Extension Attribute # Targets macOS 12 through 26 (Tahoe), Intel and Apple Silicon # Modern macOS no longer ships AFP at all (removed in 11), so we only # probe smbd. launchctl print lists running services; the legacy "list" # subcommand is still supported but print is preferred.
if /bin/launchctl list 2>/dev/null | /usr/bin/grep -q "com.apple.smbd"; then echo "<result>On</result>" else echo "<result>Off</result>" fi
